head.script:
scwin.onpageload = function() {
	wdc_main.createWindow("TEST", null, "windowContainer_modalless_page_WESE-718_(WSQ-5563)_sub1.xml", "TEST", "TEST");
};

scwin.checkVal = function() {
	return WebSquare.wUnit.getJq('#wdc_main_subWindow0_wframe').hasClass('w2modalopened_wframepopup') == false;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wdc_main_subWindow0_wframe_btn_trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest()
